import {parseWeight} from './fishing-coins-model.mjs?v=decimal2';
export function fishingImportPlan(fish,saved,records){const next={...saved},results=[],candidates=new Map();for(const record of records){const match=record.matches?.[0],item=fish.find(f=>f.id===match?.id),result={record,name:item?.name||'Unread fish',status:'skipped'};results.push(result);if(!item||!record.readable){result.reason='Fish picture is unclear.';continue;}if(!record.weight?.readable){result.reason='Weight is unclear or partly covered.';continue;}const parsed=parseWeight(record.weight.value,item);if(parsed.state!=='valid'){result.reason=parsed.message||'Weight is outside this fish’s range.';continue;}const coinUnverified=!Number.isFinite(record.coinError)||record.coinError>=8000;if(coinUnverified&&!(record.identityStrong&&record.weight.consensus>=2&&!record.weight.conflict)){result.reason='Weight needs a clearer reading or a matching coin value.';continue;}result.coinUnverified=coinUnverified;Object.assign(result,{id:item.id,weight:record.weight.value,raw:parsed.raw});const group=candidates.get(item.id)||[];group.push(result);candidates.set(item.id,group);}
 const changes=[];for(const [id,group]of candidates){group.sort((a,b)=>b.raw-a.raw||Number(a.coinUnverified)-Number(b.coinUnverified));const best=group[0],item=fish.find(f=>f.id===id),before=parseWeight(saved[id]??'',item);for(const duplicate of group.slice(1)){duplicate.status='duplicate';duplicate.reason='Highest readable weight is used.';}if(before.state==='valid'&&before.raw>=best.raw){best.status='unchanged';best.reason=before.raw>best.raw?'A higher weight is already saved.':'Already matches your record.';continue;}next[id]=best.weight;best.status='imported';changes.push({id,before:saved[id],after:best.weight});}for(const result of results){if(result.status!=='skipped'||!result.record.identityStrong||!result.record.weight?.readable)continue;const id=result.record.matches?.[0]?.id,item=fish.find(f=>f.id===id),parsed=item?parseWeight(result.record.weight.value,item):null;if(parsed?.state==='valid'&&candidates.get(id)?.some(r=>r.raw===parsed.raw)){result.status='duplicate';result.reason='Another screenshot provided a checked reading.';}}return {next,changes,results,skipped:results.filter(r=>r.status==='skipped').length,duplicates:results.filter(r=>r.status==='duplicate').length};}
